"""Explicit verified backup receipt adapter; never reads backup files or runs backups."""
from .activity_feed_hooks import event, publish, NODE
import re


def backup_event(source, *, node, run_id, outcome, at):
    # An opaque random run ID generated by the backup owner, never a file path
    # or name. Verification means the producer performed its own integrity check.
    if type(node) is not str or not NODE.fullmatch(node):
        raise ValueError("invalid backup node")
    if type(run_id) is not str or not re.fullmatch(r"[a-f0-9]{32}", run_id):
        raise ValueError("opaque backup run ID required")
    states = {"created": ("Backup created; verification not attested", "info"),
              "verified": ("Backup integrity verified", "success"),
              "failed": ("Backup operation failed", "error"),
              "verification_failed": ("Backup integrity verification failed", "error")}
    if outcome not in states:
        raise ValueError("invalid backup outcome")
    title, severity = states[outcome]
    return event(source=source, kind="backup." + outcome,
                 identity=(node, run_id), at=at, title=title, summary=node,
                 category="backup", severity=severity, node=node)


def record(*, node, run_id, outcome, at):
    return publish(lambda source: backup_event(source, node=node, run_id=run_id,
                                                outcome=outcome, at=at))


def main(argv=None):
    import argparse
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--node", required=True)
    parser.add_argument("--run-id", required=True)
    parser.add_argument("--outcome", choices=("created", "verified", "failed", "verification_failed"), required=True)
    parser.add_argument("--time", required=True)
    args = parser.parse_args(argv)
    return 0 if record(node=args.node, run_id=args.run_id, outcome=args.outcome, at=args.time) else 1


if __name__ == "__main__":
    raise SystemExit(main())
